// Auto-generated from src/assets/logo-nobg.png — do not edit by hand.
// To regenerate: `base64 -w 0 src/assets/logo-nobg.png` and replace the
// LOGO_PNG_BASE64 string below. The logo is embedded into the report PDF
// cover page by `_shared/report-pdf.ts`. Edge functions cannot read frontend
// assets at runtime, so the bytes ship inside the function bundle.

export const LOGO_PNG_BASE64 = "";

export function decodeLogoPng(): Uint8Array {
  const bin = atob(LOGO_PNG_BASE64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}
